,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'',
'',
'document.getElementById("my-home-region").addEventListener("click", function(e) {',
'  // Avoid triggering if the button itself was clicked',
'  if (!e.target.closest("#my-home-button")) {',
'    document.getElementById("my-home-button").click();',
'  }',
'});',
'',
'',
'',
'//Typing',
'const codeText = `const name = "Sridhar Utukuri";',
'const pronouns = "He/Him";',
'',
'const roles = [',
'  "Oracle Certified Cloud Expert",',
'  "APEX Developer",',
'  "Techno-Functional Consultant"',
'];',
'',
'const specialties = [',
'  "APEX", "BIP","VBCS", "OIC"',
'];',
'',
'function collaborate() {',
'  return "Open to meaningful projects!";',
'}',
'',
'`;',
'',
'let isTyping = false;',
'let typed = false;',
'let i = 0;',
'',
'function typeCode() {',
'  const codeEl = document.getElementById("typed-code");',
'  codeEl.textContent = "";',
'  i = 0;',
'  isTyping = true;',
'',
'  const interval = setInterval(() => {',
'    if (i < codeText.length) {',
'      codeEl.textContent += codeText[i];',
'      i++;',
'    } else {',
'      clearInterval(interval);',
'      isTyping = false;',
'      typed = true;',
'    }',
'  }, 12);',
'}',
'',
'document.getElementById("photoToggle").addEventListener("mouseenter", () => {',
'  const wrapper = document.getElementById("photoToggle");',
'  if (!typed && !isTyping) {',
'    wrapper.classList.add("active");',
'    typeCode();',
'  }',
'});',
'',
'document.getElementById("photoToggle").addEventListener("click", () => {',
'  const wrapper = document.getElementById("photoToggle");',
'  wrapper.classList.toggle("active");',
'});',
''))
