wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(59741675977158031238)
,p_plug_name=>'About'
,p_parent_plug_id=>wwv_flow_imp.id(59741675829879031237)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noBorder:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!DOCTYPE html>',
'<html lang="en">',
'<head>',
'  <meta charset="UTF-8" />',
'  <meta name="viewport" content="width=device-width, initial-scale=1.0" />',
'  <title>Sridhar Utukuri Portfolio</title>',
'',
'  <!-- Font Awesome for map pin icon -->',
'  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" />',
'</head>',
'<body>',
'',
'  <div class="portfolio-section about-me">',
'    <div class="about-header">',
'      <div>',
'        <h2 class="about-name">Sridhar Utukuri</h2>',
'        <p class="about-title">',
unistr('          He/Him \00B7 Oracle Certified Cloud Expert \00B7 APEX Developer \00B7 Techno-Functional Consultant'),
'        </p>',
'        <p class="about-location">',
'          <a href="https://www.google.com/maps?q=Hyderabad,+Telangana,+India" target="_blank" style="text-decoration: none; color: inherit;">',
'            <i class="fas fa-map-marker-alt" style="color: red; margin-right: 4px;"></i>',
'          </a>',
'          Hyderabad, Telangana, India',
'        </p>',
'      </div>',
'    </div>',
'',
'    <hr />',
'',
'    <p class="about-description">',
unistr('      I\2019m a certified Oracle Fusion Techno-Functional Consultant with deep expertise in'),
'      <strong>Oracle APEX</strong>, <strong>SQL/PLSQL</strong>, and',
'      <strong>Oracle Cloud tools</strong> like BIP, OTBI, FDIP, VBCS, and OIC. With a strong foundation in',
'      Oracle SCM, Financials, and HCM modules, I specialize in end-to-end enterprise app development,',
unistr('      reporting, and integration. I\2019ve successfully led several implementations, from requirement gathering to'),
unistr('      solution delivery. Passionate about problem-solving and innovation, I\2019m always open to collaborating on'),
'      meaningful Oracle projects.',
'    </p>',
'',
'    <ul class="about-list">',
'      <li><strong>Specialties:</strong> Oracle APEX, BIP/OTBI, VBCS, OIC, FBDI, ESS Jobs, ADFDI, BICC</li>',
'      <li><strong>Modules:</strong> Manufacturing, Inventory, Procurement, Order Management, Financials, HR</li>',
unistr('      <li><strong>Experience:</strong> Accelalpha \2013 Consultant, over 5 APEX projects delivered, integrations implemented</li>'),
'    </ul>',
'  </div>',
'',
'</body>',
'</html>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
