wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(67696166685345468806)
,p_plug_name=>'projects-region'
,p_title=>'Projects'
,p_region_name=>'projects-region'
,p_parent_plug_id=>wwv_flow_imp.id(59741675829879031237)
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>50
,p_plug_display_point=>'SUB_REGIONS'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="project-showcase">',
'  <div id="project-display"></div>',
'',
'  <!-- Dot Indicators -->',
'  <div id="project-indicators" class="project-indicators"></div>',
'</div>',
'',
'<script>',
'  const projects = [',
'    {',
'      title: "Supplier Onboarding App",',
unistr('      timeframe: "Jan 2023 \2013 Apr 2023",'),
'      tech: "Oracle APEX, PL/SQL",',
'      desc: "Developed an application for vendor registration, with workflow approvals, document upload, and supplier dashboard."',
'    },',
'    {',
'      title: "Inventory Tracker",',
unistr('      timeframe: "May 2023 \2013 Jul 2023",'),
'      tech: "Oracle SCM, BI Publisher",',
'      desc: "Created a system to monitor stock across multiple warehouses with automatic replenishment triggers and exception alerts."',
'    },',
'    {',
'      title: "Fusion-OIC Integration",',
unistr('      timeframe: "Aug 2023 \2013 Sep 2023",'),
'      tech: "Oracle Integration Cloud, FBDI",',
'      desc: "Automated integration between Oracle Fusion and external CRM using scheduled FBDI processes and REST APIs."',
'    },',
'    {',
'      title: "HR Analytics Dashboard",',
unistr('      timeframe: "Oct 2023 \2013 Nov 2023",'),
'      tech: "OTBI, BI Publisher",',
'      desc: "Built a KPI-driven dashboard for HR metrics, with department-wise filtering and export features."',
'    },',
'    {',
'      title: "Customer Service Portal",',
unistr('      timeframe: "Dec 2023 \2013 Feb 2024",'),
'      tech: "APEX, VBCS",',
'      desc: "Developed a responsive portal for customer ticketing and feedback, integrated with backend service workflows."',
'    }',
'  ];',
'',
'  let currentIndex = 0;',
'  let interval;',
'',
'  function renderProject(index) {',
'    const p = projects[index];',
'    const html = `',
'      <div class="project-text-block left">',
'        <h3 class="project-title">${p.title}</h3>',
'        <p><strong>Timeframe:</strong> ${p.timeframe}</p>',
'        <p><strong>Technologies:</strong> ${p.tech}</p>',
'      </div>',
'      <div class="project-text-block right">',
'        <p>${p.desc}</p>',
'      </div>',
'    `;',
'    document.getElementById("project-display").innerHTML = html;',
'    renderIndicators();',
'  }',
'',
'  function goToProject(index) {',
'    currentIndex = index;',
'    renderProject(currentIndex);',
'    restartRotation();',
'  }',
'',
'  function renderIndicators() {',
'    const indicatorContainer = document.getElementById("project-indicators");',
'    indicatorContainer.innerHTML = projects.map((_, idx) => `',
'      <button type="button" onclick="goToProject(${idx})" class="${idx === currentIndex ? ''active'' : ''''}"></button>',
'    `).join('''');',
'  }',
'',
'  function showNextProject() {',
'    currentIndex = (currentIndex + 1) % projects.length;',
'    renderProject(currentIndex);',
'  }',
'',
'  function startRotation() {',
'    interval = setInterval(showNextProject, 5000);',
'  }',
'',
'  function restartRotation() {',
'    clearInterval(interval);',
'    startRotation();',
'  }',
'',
'  // Initialize',
'  renderProject(currentIndex);',
'  startRotation();',
'</script>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
